begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(142626454538482188)
,p_plugin_type=>'ITEM TYPE'
,p_name=>'AAK.JSONVIEWER.PLUGIN'
,p_display_name=>'json_viewer'
,p_apexlang_name=>'jsonViewer'
,p_supported_component_types=>'APEX_APPLICATION_PAGE_ITEMS:APEX_APPL_PAGE_IG_COLUMNS'
,p_image_prefix=>nvl(wwv_flow_application_install.get_static_plugin_file_prefix('ITEM TYPE','AAK.JSONVIEWER.PLUGIN'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'procedure render_json_viewer(',
'    p_item   in            apex_plugin.t_item,',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_param  in            apex_plugin.t_item_render_param,',
'    p_result in out nocopy apex_plugin.t_item_render_result ) ',
'is',
'  l_name          varchar2(30)    := apex_plugin.get_input_name_for_page_item(false);',
'  v_html clob;',
'',
'begin',
'           ',
'',
'',
'-- load css and javascript',
'apex_javascript.add_library (p_name => ''js/json-viewer'' , p_directory => p_plugin.file_prefix); ',
'apex_css.add_file  (p_name => ''css/json-viewer'' , p_directory => p_plugin.file_prefix); ',
'',
'htp.p(''<div '' || ''id="'' || p_item.name ||''" '' ',
'              || ''name="'' || l_name ||''" '' ',
'              ||  p_item.element_attributes ||'' ></div>'');',
'',
'v_html:=v_html || ''$("#'' || p_item.name || ''_LABEL").remove();'';',
'v_html:=v_html || ''$("#'' || p_item.name || ''").jsonview('''''' || p_param.value || '''''');'';',
'',
'apex_javascript.add_onload_code(',
'         p_code => v_html,',
'         p_key => NULL);    ',
'end;'))
,p_api_version=>2
,p_render_function=>'render_json_viewer'
,p_item_session_state_data_type=>'VARCHAR2'
,p_standard_attributes=>'SOURCE:FORMAT_MASK_DATE:ELEMENT:WIDTH:HEIGHT:PLACEHOLDER:ICON:ENCRYPT:LINK:INIT_JAVASCRIPT_CODE'
,p_substitute_attributes=>true
,p_version_scn=>'236555912'
,p_version_identifier=>'1.0'
,p_files_version=>5
);
wwv_flow_imp_shared.create_plugin_std_attribute(
 p_id=>wwv_flow_imp.id(75201202152327521)
,p_plugin_id=>wwv_flow_imp.id(142626454538482188)
,p_name=>'INIT_JAVASCRIPT_CODE'
,p_is_required=>false
);
end;
