prompt --application/shared_components/logic/application_processes/download_json
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(6656170883778830)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_name=>'DOWNLOAD_JSON'
,p_static_id=>'download-json'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'v_filename VARCHAR2(200):=''File.json'';',
'',
'BEGIN',
'    FOR file IN (SELECT ID_LOG,',
'                        V_filename,',
'                        VL_PARAMETER,',
'                        VL_MIMETYPE   ',
'                 FROM VL_LOGS WHERE ID_LOG = TO_NUMBER(:ID_PARAMETER)',
'        ) LOOP',
'        -- Inicializar la respuesta HTTP',
'        sys.htp.init;',
'        sys.owa_util.mime_header(file.VL_MIMETYPE, FALSE);',
'',
'        -- Incluir la longitud del archivo y el nombre en el encabezado',
'        sys.htp.p(''Content-length: '' || sys.dbms_lob.getlength(file.VL_PARAMETER));',
'        sys.htp.p(''Content-Disposition: attachment; filename="'' || file.v_filename || ''"'');',
unistr('        sys.htp.p(''Cache-Control: max-age=3600'');  -- Indicar al navegador que guarde en cach\00E9 por 1 hora'),
'',
'        ',
'        sys.owa_util.http_header_close;',
'        sys.wpg_docload.download_file(file.VL_PARAMETER);',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>'235604987'
);
end;
