 p_id=>wwv_flow_imp.id(62041755304869069)
,p_validation_name=>'VLDT_FORMAT_PASS'
,p_static_id=>'vldt-format-pass'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
unistr('  -- Verificar si la contrase\00F1a es nula o vac\00EDa'),
'  IF :P2_NEW_PASS IS NULL OR TRIM(:P2_NEW_PASS) = '''' THEN',
unistr('    RETURN ''Es necesario proporcionar una contrase\00F1a para continuar.'';'),
'  END IF;',
'',
unistr('  -- Verificar la longitud de la contrase\00F1a'),
'  IF LENGTH(:P2_NEW_PASS) >= 8 AND LENGTH(:P2_NEW_PASS) <= 15 THEN',
unistr('    -- Verificar si contiene un n\00FAmero'),
'    IF REGEXP_LIKE(:P2_NEW_PASS, ''[0-9]'') THEN',
unistr('      -- Verificar si contiene una letra min\00FAscula'),
'      IF REGEXP_LIKE(:P2_NEW_PASS, ''[a-z]'', ''c'') THEN',
unistr('        -- Verificar si contiene una letra may\00FAscula'),
'        IF REGEXP_LIKE(:P2_NEW_PASS, ''[A-Z]'', ''c'') THEN',
unistr('          -- Verificar si contiene un car\00E1cter especial'),
'          IF REGEXP_LIKE(:P2_NEW_PASS, ''[,.!@#$%^&*()_]'', ''c'') THEN',
unistr('            RETURN ''''; -- Contrase\00F1a v\00E1lida'),
'          ELSE',
unistr('            RETURN ''La contrase\00F1a debe contener al menos un car\00E1cter especial, como uno de los siguientes: [,.!@#$%^&*()_]'';'),
'          END IF;',
'        ELSE',
unistr('          RETURN ''La contrase\00F1a debe contener al menos una letra may\00FAscula.'';'),
'        END IF;',
'      ELSE',
unistr('        RETURN ''La contrase\00F1a debe contener al menos una letra min\00FAscula.'';'),
'      END IF;',
'    ELSE',
unistr('      RETURN ''La contrase\00F1a debe contener al menos un n\00FAmero.'';'),
'    END IF;',
'  ELSE',
unistr('    RETURN ''La contrase\00F1a debe tener entre 8 y 15 caracteres. El tama\00F1o actual es: '' || LENGTH(:P2_NEW_PASS);'),
'  END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_always_execute=>'Y'
,p_associated_item=>wwv_flow_imp.id(62040961386869061)
