 p_id=>wwv_flow_imp.id(62184102184454527)
,p_event_id=>wwv_flow_imp.id(62184043266454526)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P3_RETURN',
  'items_to_submit', 'P3_EMAIL',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    ' declare',
    '    li_token clob;',
    '    v_email clob;',
    'begin',
    '   ',
    '    if VL_PKG_RESTORE.VL_RESTORE(UPPER(:P3_EMAIL)) THEN',
    '        ',
    '        select dbms_random.string(''A'', 60) into li_token from dual;',
    '        select STANDARD_HASH(EMAIL,''SHA256'') into v_email ',
    '        from VL_USERS',
    '        where EMAIL= UPPER(:P3_EMAIL);',
    '     ',
    '        update VL_USERS set TOKEN=li_token, TIME_EXPIRED=CURRENT_TIMESTAMP + interval ''10'' minute ',
    '        where EMAIL=  UPPER(:P3_EMAIL);',
    '        ',
    '        ',
    '          apex_mail.send(p_from => ''notification@veranoglobal.com'', ',
    '        p_to => :P3_EMAIL, ',
    '        p_template_static_id => ''EMAILTRY'',',
    '        p_placeholders       => ''{'' ||',
    '        '' "APPLICATION_LINK":''      || apex_json.stringify(''https://apps.veranocloud.com.co'' || apex_page.get_url(',
    '                                        p_application => 140,',
    '                                        p_page => 9998,',
    '                                        p_plain_url =>true,',
    '                                        p_session => null,',
    '                                        p_items  => ''P9998_EMAIL,P9998_TOKEN'',',
    '                                        p_values =>  v_email || '','' || li_token)) ||',
    '        ''}'' );',
    '        ',
    '        apex_mail.push_queue();',
    '        ',
    '        :P3_RETURN:=1;',
    '    else',
    '        :P3_RETURN:=0;',
    '    end if;',
    '',
    'end;')),
  'show_processing', 'Y',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
);
end;
