  'items_to_return', 'P7_MESSAGE_RESPONSE',
  'items_to_submit', 'P7_NAME,P7_VL_ID_COUNTRY,P7_ALIAS',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    'VALIDATOR NUMBER;',
    'BEGIN',
    'SELECT COUNT(*) INTO VALIDATOR FROM VL_COMPANIES WHERE SHORT_NAME = UPPER(:P7_ALIAS);',
    '',
    'IF VALIDATOR = 0 THEN',
    '',
    'VL_PKG_CRUD_COMPANY.NEW_COMPANY(:P7_NAME, :P7_VL_ID_COUNTRY, :P7_ALIAS);',
    ':P7_MESSAGE_RESPONSE := 1;',
    '',
    'ELSE ',
    ':P7_MESSAGE_RESPONSE := 0;',
    'END IF;',
    '',
    'exception WHEN OTHERS THEN  ',
    'IF SQLCODE = -01920 THEN ',
    ':P7_MESSAGE_RESPONSE := 2;',
    'DELETE FROM VL_COMPANIES WHERE SHORT_NAME = UPPER(:P7_ALIAS);',
    'END IF;',
    '',
    'END;',
    '')),
  'show_processing', 'Y',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
);
