wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(62040046323869052)
,p_process_sequence=>80
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'spActualizarUsuario'
,p_static_id=>'spactualizarusuario'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'l_elements varchar2(50);',
'',
'BEGIN',
'IF :GET_ROL = 1 THEN ',
'VL_PKG_CRUD_USER.UPDATE_USER (:P9_NAME, :P9_EMAIL,:P9_VL_ID_COMPANY_SA, :P9_VL_ID_ROL_SA, :P9_STATE, :P9_VL_ID_USER);',
'ELSIF :GET_ROL = 2 THEN',
'VL_PKG_CRUD_USER.UPDATE_USER (:P9_NAME, :P9_EMAIL, :GET_COMPANY, :P9_VL_ID_ROL_AD, :P9_STATE, :P9_VL_ID_USER);',
'END IF;',
'',
'',
'select listagg(:P9_SL_SOURCES, '':'') into l_elements from dual;',
'',
'VL_PKG_CRUD_USER.UPDATE_USER_SOURCES(l_elements, :P9_VL_ID_USER);',
'',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(62016970636925376)
,p_process_success_message=>'Usuario actualizado'
,p_internal_uid=>3205064969819531
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(62038523385869037)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'spCrearUsuario'
,p_static_id=>'spcrearusuario'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'DECLARE',
'',
'    l_elements varchar2(50);',
'    v_id number;',
'',
'BEGIN',
'',
'    IF :GET_ROL = 1 THEN ',
'        v_id := VL_PKG_CRUD_USER.NEW_USER (:P9_NAME, :P9_EMAIL, :P9_PASSWORD, :P9_VL_ID_COMPANY_SA, :P9_VL_ID_ROL_SA);',
'',
'    ELSIF :GET_ROL = 2 THEN',
'        v_id := VL_PKG_CRUD_USER.NEW_USER (:P9_NAME, :P9_EMAIL, :P9_PASSWORD, :GET_COMPANY, :P9_VL_ID_ROL_AD);',
'        select listagg(:P9_SL_SOURCES, '':'') into l_elements from dual;',
'        VL_PKG_CRUD_USER.UPDATE_USER_SOURCES(l_elements, v_id);',
'',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(62017317502925376)
,p_process_success_message=>'Usuario Creado'
,p_internal_uid=>3203542031819516
);
end;
