wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(66966405753608269)
,p_event_id=>wwv_flow_imp.id(66966380848608268)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P12_CREATE_RESPONSE',
  'items_to_submit', 'P12_NAME_TABLE',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    'validator number;',
    'BEGIN',
    '',
    '',
    'select COUNT(*) INTO VALIDATOR from all_tables where owner = :GET_COMPANY_NAME AND TABLE_NAME = UPPER(:P12_NAME_TABLE);',
    '',
    '',
    'IF REGEXP_LIKE(:P12_NAME_TABLE,''^[a-zA-Z_-]*$'') THEN ',
    'IF validator = 0 THEN ',
    '    :P12_CREATE_RESPONSE := 0;',
    'ELSE',
    '    :P12_CREATE_RESPONSE := 1;',
    ' END IF;',
    '',
    ' ELSE ',
    ' :P12_CREATE_RESPONSE := 2;',
    ' END IF;',
    'END;')),
  'show_processing', 'Y',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
);
