  'items_to_return', 'P22_VALIDATE_QUERY',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    'l_query VARCHAR2(32676);',
    'BEGIN',
    'l_query := ''SELECT count(*) FROM "''||:GET_COMPANY_NAME||''"."VIEW_''||UPPER(:CUSTOM_REPORT_NAME)||''"'';',
    '--   execute immediate ''CREATE OR REPLACE VIEW VISTAFEA  AS (''|| l_query ||'')'';',
    '--   l_query := ''select * from "RENOBO"."VIEW_ASD"'';',
    '  ',
    'APEX_COLLECTION.CREATE_COLLECTION_FROM_QUERY (',
    '    p_collection_name   => ''AUTO'',',
    '    p_query           =>  l_query,',
    '    p_truncate_if_exists => ''YES'');',
    '    :P22_VALIDATE_QUERY := 1;',
    '    EXCEPTION WHEN OTHERS THEN ',
    '    :P22_VALIDATE_QUERY := 0;',
    'END;')),
  'show_processing', 'Y',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
,p_server_condition_type=>'NEVER'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(72927912845168425)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'update_shutle'
,p_static_id=>'update-shutle'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    cursor col_csr is',
'        select seq_id',
'        from apex_collections',
'        where collection_name = ''COLUMNS'';',
'    col_rec col_csr%ROWTYPE;',
'    shtl apex_application_global.vc_arr2;',
'begin',
'    -- Loop through the collection, setting display sequence to null and',
'    -- display in report to N. We''ll clean up in a bit.',
'    for col_rec in col_csr loop',
'        apex_collection.update_member_attribute(',
'            p_collection_name => ''COLUMNS'',',
'            p_seq => col_rec.seq_id,',
'            p_attr_number => 4,',
'            p_number_value => null );',
'        apex_collection.update_member_attribute(',
'            p_collection_name => ''COLUMNS'',',
'            p_seq => col_rec.seq_id,',
'            p_attr_number => 5,',
'            p_attr_value => ''N'' );',
'    end loop;',
'    -- Now, go through the shuttle''s values, setting the display',
'    -- flag and sequence properly.',
'    shtl := apex_util.string_to_table( :P22_COLUMNS );',
'    for i in 1..shtl.COUNT loop',
'        apex_collection.update_member_attribute(',
'            p_collection_name => ''COLUMNS'',',
'            p_seq => shtl(i),',
'            p_attr_number => 4,',
'            p_number_value => i );',
'        apex_collection.update_member_attribute(',
'            p_collection_name => ''COLUMNS'',',
'            p_seq => shtl(i),',
'            p_attr_number => 5,',
'            p_attr_value => ''Y'' );',
'    end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_type=>'NEVER'
,p_internal_uid=>14092931491118904
);
end;
