wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(75845927739295208)
,p_name=>'Logs de APIS'
,p_static_id=>'logs-de-apis'
,p_region_name=>'LogApi'
,p_template=>wwv_flow_imp.id(61391316235918365)
,p_display_sequence=>30
,p_region_css_classes=>'search-results'
,p_region_template_options=>'#DEFAULT#:margin-right-none'
,p_component_template_options=>'#DEFAULT#:u-colors:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    MIN(ID_LOG) AS ID_LOG,',
'    ',
'    MIN(VL_AUDIT_LOG) AS LINK_CLASS,',
'    NULL AS ICON_CLASS,',
'    NULL AS LINK_ATTR,',
'    NULL AS ICON_COLOR_CLASS,',
'    NULL AS LIST_CLASS,',
'    apex_page.get_url(p_items => ''P26_NAME_API,P26_VL'', p_values => MIN(VL_NAME_API) || '','' || MIN(VL_AUDIT_LOG)) AS LINK,',
'',
'    SUBSTR(MIN(VL_NAME_API), 1, 60) || ',
'    CASE ',
'        WHEN LENGTH(MIN(VL_NAME_API)) > 60 THEN ''...'' ',
'        ELSE '''' ',
'    END AS LIST_TITLE,',
'    ',
unistr('   ''\00DAltima sincronizaci\00F3n: '' || TO_CHAR(MAX(VL_TIMESTAMP), ''DD-MM-YYYY HH:MI:SS AM'') AS LIST_TEXT,'),
'',
'    ',
'    SUBSTR(MIN(VL_AUDIT_LOG), 1, 50) || ',
'    CASE ',
'        WHEN LENGTH(MIN(VL_AUDIT_LOG)) > 50 THEN ''...'' ',
'        ELSE '''' ',
'    END AS LIST_TEXT_2,',
'',
'    NULL AS LIST_BADGE',
'FROM',
'    VL_LOGS v_log',
'LEFT JOIN VL_PATH_CONTEXTS vpc',
'    ON v_log.ID_VL_PATH_CONTEXT = vpc.ID_VL_PATH_CONTEXT',
'WHERE',
'    COMPANY_SHORTNAME = :GET_COMPANY_NAME AND (',
'        :P26_BUSQUEDA IS NULL',
'        OR UPPER(v_log.VL_NAME_API) LIKE ''%'' || UPPER(:P26_BUSQUEDA) || ''%''',
'    ) ',
'GROUP BY',
'    VL_NAME_API',
'ORDER BY',
'    MAX(VL_TIMESTAMP) DESC;',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P26_LOG,P26_BUSQUEDA,P26_NAME_API,P26_VL'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(61407293731918357)
,p_query_num_rows=>300
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No hay datos aun '
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
