wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(6983085397547552)
,p_event_id=>wwv_flow_imp.id(5088945642202066)
,p_event_result=>'TRUE'
,p_action_sequence=>40
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '(function () {',
    '  var parameterValue = $v("P26_VL_PARAMETERS");',
    '',
    '  $(".my_json_item").empty(); // Limpiar contenido previo',
    '',
    '  if (!parameterValue || parameterValue.trim() === "") {',
    unistr('    document.querySelector(".my_json_item").textContent = "No se usaron par\00E1metros.";'),
    '    ',
    '  } else {',
    '    document.querySelector(".my_json_item").textContent = parameterValue;',
    '    $("cc-clear-btn").hide();',
    '    try {',
    '      var json = JSON.parse(parameterValue);',
    '',
    '    ',
    '      $(".my_json_item").JSONView(json, { collapsed: true }); ',
    '',
    '      ',
    '      $("#expandBtn").on("click", function (event) {',
    '        event.preventDefault(); ',
    '        $(".my_json_item").JSONView(''expand''); // Expande todo el JSON',
    '      });',
    '',
    ' ',
    '      $("#collapseBtn").on("click", function (event) {',
    '        event.preventDefault(); ',
    '        $(".my_json_item").JSONView(''collapse''); // Colapsa todo el JSON',
    '      });',
    '     ',
    '    } catch (e) {',
    unistr('      console.error("El valor no es un JSON v\00E1lido:", e);'),
    '    }',
    '  }',
    '})();',
    '')))).to_clob
);
