wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(7995230391994173)
,p_event_id=>wwv_flow_imp.id(7995134919994172)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P29_VALIDATOR',
  'items_to_submit', 'P29_JOB_NAME,P29_ENABLED,P29_REPEAT_INTERVAL,P29_DESCRIPTION,P29_JOB_INTERVAL',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '    v_job_name        VARCHAR2(100) := :P29_JOB_NAME;       -- Nombre del job',
    '    v_new_state       VARCHAR2(5) := :P29_ENABLED;          -- Estado: ''TRUE'' o ''FALSE''',
    '    v_new_interval    VARCHAR2(4000) := :P29_REPEAT_INTERVAL; -- Nuevo repeat_interval',
    '    v_job_interval    NUMBER;                               -- Intervalo proporcionado',
    'BEGIN',
    unistr('    -- Validar que P29_JOB_INTERVAL sea un n\00FAmero'),
    '    v_job_interval := TO_NUMBER(TRIM(:P29_JOB_INTERVAL));',
    '',
    unistr('    -- Validar que P29_JOB_INTERVAL est\00E9 entre 1 y 100'),
    '    IF v_job_interval >= 1 AND v_job_interval <= 99 THEN',
    '',
    '        --:P29_VALIDATOR := v_job_interval;',
    '        -- Actualizar el estado del job',
    '        IF v_new_state = ''FALSE'' THEN',
    '            DBMS_SCHEDULER.DISABLE(name => v_job_name);',
    '        ELSE',
    '            DBMS_SCHEDULER.ENABLE(name => v_job_name);',
    '        END IF;',
    '',
    '        -- Actualizar el repeat_interval',
    '        DBMS_SCHEDULER.SET_ATTRIBUTE(',
    '            name      => v_job_name,',
    '            attribute => ''repeat_interval'',',
    '            value     => v_new_interval',
    '        );',
    '',
    '        -- Actualizar el comentario',
    '        DBMS_SCHEDULER.SET_ATTRIBUTE(',
    '            name      => v_job_name,',
    '            attribute => ''comments'',',
    '            value     => :P29_DESCRIPTION',
    '        );',
    '',
    '        -- Configurar la hora de inicio a la hora actual + 1 minuto',
    '        DBMS_SCHEDULER.SET_ATTRIBUTE(',
    '            name      => v_job_name,',
    '            attribute => ''start_date'',',
    '            value     => SYSTIMESTAMP + INTERVAL ''1'' MINUTE',
    '        );',
    '',
    '        :P29_VALIDATOR := 1;',
    '    ELSE',
    unistr('        -- Si no cumple con la validaci\00F3n, asignar 0 a P29_VALIDATOR'),
    '        :P29_VALIDATOR := 0;',
    '    END IF;',
    '',
    'EXCEPTION',
    '    WHEN VALUE_ERROR THEN',
    unistr('        -- Si ocurre un error de conversi\00F3n, asignar 0 a P29_VALIDATOR'),
    '        :P29_VALIDATOR := 2;',
    '    WHEN OTHERS THEN',
    '        -- Manejo general de errores',
    '        :P29_VALIDATOR := 0;',
    'END;')),
  'show_processing', 'Y',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
);
